{"css":["@font-face { font-family: Display; src: url("/assets/display.ttf") format("truetype"); font-style: normal; font-weight: 400; font-display: swap; }
@font-face { font-family: Manticore; src: url("/assets/manticore.woff2") format("woff2"); font-style: normal; font-weight: 400; font-display: swap; }
:root { --ink: #090f0e; --accent: #b9cbb7; --paper: #e7e9d8; --muted: #a7b3a7; --line: #35463d; --amber: #d9b47b; --mist: #c4d1c0; --surface: #192a23; --pad: clamp(24px,4.6vw,88px); --display: Display,Impact,'Arial Narrow',sans-serif; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 88px; }
body { margin: 0px; background: var(--ink); color: var(--paper); font-family: Arial, Helvetica, sans-serif; -webkit-font-smoothing: antialiased; overflow-x: clip; }
body::after { content: ""; position: fixed; inset: 0px; pointer-events: none; z-index: 40; opacity: 0.04; transform: translateZ(0px); background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Cpath fill='%23fff' filter='url(%23n)' opacity='.8' d='M0 0h180v180H0z'/%3E%3C/svg%3E"); }
::selection { background: var(--accent); color: var(--ink); }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; }
button, a, summary { -webkit-tap-highlight-color: transparent; }
a:focus-visible, button:focus-visible, summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 7px; }
.zombies a:focus-visible { outline-color: var(--ink); }
img { display: block; width: 100%; height: auto; object-fit: cover; }
h1, h2, h3, p, figure { margin: 0px; }
h2, h3 { font-family: var(--display); font-weight: 400; }
p { font-size: clamp(16px, 1.35vw, 20px); line-height: 1.65; }
section { position: relative; isolation: isolate; }
section[id] { scroll-margin-top: 0px; }
.section-pad { padding: 45px var(--pad) 95px; }
.eyebrow, .section-kicker, .hero-topline, .hero-coordinates, .tour-facts span, .story-tag, .story-count, .zombies-photo figcaption, .local-index, .ticket-note { font-size: 12px; line-height: 1.5; text-transform: uppercase; letter-spacing: 0.11em; }
.section-kicker { display: flex; justify-content: space-between; gap: 30px; border-top: 1px solid var(--line); padding-top: 17px; }
