.site-header { position: absolute; inset: 0px 0px auto; display: flex; align-items: center; justify-content: space-between; gap: 25px; height: 110px; padding: 0 var(--pad); z-index: 50; color: var(--paper); }
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { font-family: var(--display); color: var(--accent); border: 1px solid var(--accent); height: 47px; width: 43px; display: flex; align-items: center; justify-content: center; font-size: 30px; line-height: 1; }
.brand-mark span { font-size: 15px; writing-mode: vertical-rl; letter-spacing: 0px; }
