.menu-open .site-header { position: fixed; }
.hero { min-height: 800px; height: 100svh; max-height: 1400px; padding: 146px var(--pad) 55px; display: flex; flex-direction: column; overflow: hidden; background: rgb(9, 15, 14); }
.hero-media, .hero-shade { position: absolute; inset: 0px; z-index: -1; }
