.haunted-word { color: var(--amber); display: block; font-family: Manticore,var(--display); font-size: clamp(110px, 18.8vw, 207px); letter-spacing: -0.035em; line-height: 0.94; padding-bottom: 3px; }
.city-word { color: var(--paper); font-family: var(--display); font-size: clamp(73px, 11.8vw, 228px); letter-spacing: -0.005em; display: block; white-space: nowrap; }
