.marquee { background: var(--amber); color: var(--ink); overflow: hidden; padding: 20px 0px; position: relative; z-index: 2; transform: rotate(-1.5deg); width: 102%; margin-left: -1%; margin-top: -13px; }
.marquee-track { display: flex; gap: 45px; width: max-content; align-items: center; animation: 35s linear 0s infinite normal none running marquee; }
.marquee span { font-family: var(--display); font-size: 27px; text-transform: uppercase; letter-spacing: 0.02em; }
.marquee i { font-style: normal; font-size: 26px; }
.intro { padding-top: 78px; min-height: 110svh; }
