.intro h2 > span { color: var(--mist); }
.intro-bottom { display: flex; justify-content: space-between; align-items: center; margin: 35px 0px 65px; }
.intro-bottom p { max-width: 535px; margin-right: 3%; }
.large-asterisk { font-size: clamp(80px, 13vw, 200px); line-height: 1; color: var(--amber); display: inline-block; will-change: transform; }
.tour-facts { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 30px 0px; }
.tour-facts > div { display: flex; gap: 25px; align-items: center; padding: 0px 35px; border-right: 1px solid var(--line); }
.tour-facts > div:first-child { padding-left: 0px; }
.tour-facts > div:last-child { border: 0px; }
.tour-facts strong { font-family: var(--display); font-weight: 400; font-size: 75px; line-height: 1; white-space: nowrap; }
.tour-facts strong span { font-family: var(--display); font-size: 32px; margin-left: 4px; }
.tour-facts > div > span { max-width: 140px; color: var(--muted); }
.stories-scroll { height: 340svh; background: rgb(12, 23, 19); }
