.stories-pin.history-active .scroll-instruction { color: var(--amber); }
.stories-pin.history-active .story-tabs button.is-active { color: var(--amber); border-color: var(--amber); }
.zombies { background: var(--accent); color: var(--ink); min-height: 105svh; padding-bottom: 100px; }
